def version_sql(self, expression: exp.Version) -> str:
    this = f"FOR {expression.name}"
    kind = expression.text("kind")
    expr = self.sql(expression, "expression")
    return f"{this} {kind} {expr}"

def tuple_sql(self, expression: exp.Tuple) -> str:
